('176', 'LC-AEM-AD(Firework)-CM-WL-PXFLW_floating_video_player', '2', '6', 'home|shop home|microsite|offer main|offer detail|search result|ai\\-search|product category detail|shop category|product finder|business product finder|product detail|flagship pdp|shop detail|business ', '1', '1', '2026-09-11', NULL, 'https://experience.adobe.com/#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRa7cdc4dd00c24675812c3d05053e3cf3/rules/RLbbd96c2838cc4b4bb617e07a55bdc3fc', 'Shereen El Gendy', 'shereen.g@partner.samsung.com', '1', NULL, NULL, '1', '2026-07-06 09:01:20', '0', '2026-05-21 17:25:30', '0', NULL, 'document.addEventListener(\'fw:player:quit\', function (event) {\r\n    setCookie(\'fw:player:quit\', cookieBannerValue, 0.5);\r\n})\r\n\r\nvar cookieBannerValue = \'1\';\r\n\r\nfunction setCookie(cName, cValue, expMins) {\r\n    var date = new Date();\r\n    date.setTime(date.getTime() + (expMins * 60 * 1000));\r\n    var expires = \"expires=\" + date.toUTCString();\r\n    document.cookie = cName + \"=\" + cValue + \"; \" + expires + \"; path=/\";\r\n}\r\n\r\nfunction getCookie(cname) {\r\n    var name = cname + \"=\";\r\n    var cookie_data = document.cookie.split(\';\');\r\n    for (var i = 0; i < cookie_data.length; i++) {\r\n        var cookie_value = cookie_data[i];\r\n        while (cookie_value.charAt(0) == \' \') {\r\n            cookie_value = cookie_value.substring(1);\r\n        }\r\n        if (cookie_value.indexOf(name) == 0) {\r\n            return cookie_value.substring(name.length, cookie_value.length);\r\n        }\r\n    }\r\n    return \"\";\r\n}\r\n\r\nconst PLAYLIST_MAP = {\r\n    ae: {\r\n        \'flagship pdp\': \'5DXVrY\',\r\n        \'offer main\': \'gpl7Yj\',\r\n    },\r\n    ae_ar: {\r\n        \'flagship pdp\': \'5DXVrY\',\r\n        \'offer main\': \'gpl7Yj\',\r\n    },\r\n};\r\n\r\nfunction getPlaylist(siteCode, pageTrack) {\r\n    const siteMap = PLAYLIST_MAP[siteCode];\r\n    return siteMap ? siteMap[pageTrack] : \'oPNw8q\';\r\n}\r\n\r\nif (getCookie(\'fw:player:quit\') == \"\") {\r\n    var script_el = document.createElement(\'script\');\r\n    script_el.src = \"https://asset.fwcdn3.com/js/storyblock.js\";\r\n    script_el.type = \'text/javascript\';\r\n    script_el.async = true;\r\n    document.head.appendChild(script_el);\r\n\r\n    var pageTrack = digitalData.page.pageInfo.pageTrack;\r\n    var siteCode = digitalData.page.pageInfo.siteCode;\r\n\r\n    var node = document.createElement(\"fw-storyblock\");\r\n    node.setAttribute(\"id\", \"firework-embed\");\r\n    node.setAttribute(\"channel\", \"samsung_uae\");\r\n    // node.setAttribute(\"livestream_allow_usename_change\", \"false\");\r\n    node.setAttribute(\"playlist\", getPlaylist(siteCode, pageTrack));\r\n    node.setAttribute(\"autoplay\", \"true\");\r\n    node.setAttribute(\"clear_player_state\", \"true\");\r\n    node.setAttribute(\"mode\", \"pinned\");\r\n    node.setAttribute(\"player_placement\", \"bottom-right\");\r\n    document.body.prepend(node);\r\n}'),
