('252', 'LC-Shop-AD(RTBHouse)-OrderConfirmation-WL-SDSME_aaf6-d1164146cf4e', '16', '4', '^shop order confirmation$', '4', '1', '2026-08-02', NULL, 'https://experience.adobe.com/?lens_env=prod&reactor-lens_version=prod20250220203018#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRffb0b6442ddd47769aad5467c2e4064f/rules/RL5f446f1a5697457b8bd94f54be97daee', 'Muhammad Hussnain Hamid', 'hussnain.h@partner.samsung.com', '1', NULL, NULL, '1', '2026-07-06 09:56:29', '1', '2026-06-01 12:20:10', '0', NULL, 'var eCommerce = digitalData.ecommerce;\r\nvar pageInfo = digitalData.page.pageInfo;\r\nvar products = eCommerce.transactionProducts;\r\n\r\nconst value = eCommerce.transactionTotal;\r\nconst currency = pageInfo.currencyCode;\r\nconst orderId = eCommerce.transactionId;\r\nconst IDs = products.map(p => p.modelCode);\r\nconst uid = digitalData.user?.custID != \'\' ? digitalData.user?.custID : \'unknown\';\r\n\r\nif (orderId == \'\')\r\n  return false;\r\n\r\n(rtbhEvents = window.rtbhEvents || []).push({\r\n    eventType: \'conversion\',\r\n    conversionClass: \'order\',\r\n    conversionSubClass: \'purchase\',\r\n    conversionId: orderId,\r\n    offerIds: IDs,\r\n    conversionValue: value,\r\n    conversionCurrency: currency,\r\n},\r\n{\r\n    eventType: \'uid\',\r\n    id: uid,\r\n});'),
('253', 'LC-AEM-AD(RTBHouse)-ViewContent-WL-SDSME_aaf6-d1164146cf4e', '13', '4', '^product detail$|^flagship pdp$', '1', '1', '2026-08-02', NULL, 'https://experience.adobe.com/?lens_env=prod&reactor-lens_version=prod20250220203018#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PR6bfef153a2dd4445b50f1d75982684b8/rules/RL0c661db2cd664e06830b4dcefe78c6eb', 'Muhammad Hussnain Hamid', 'hussnain.h@partner.samsung.com', '1', NULL, NULL, '1', '2026-06-30 11:41:15', '1', '2026-06-01 12:21:12', '0', NULL, 'var product = digitalData.product;\r\nvar IDs = product.model_code == \'\' ? product.model_name : product.model_code;\r\nvar UID = digitalData.user?.custID ?? \'unknown\';\r\n\r\n(rtbhEvents = window.rtbhEvents || []).push(\r\n    {\r\n        eventType: \'offer\',\r\n        offerId: IDs.trim().split(\',\').filter(item => item)[0],\r\n    },\r\n    {\r\n        eventType: \'uid\',\r\n        id: UID,\r\n    }\r\n);'),
