('492', 'LC-Shop-AD(Firework)-CM-ALL-WL-SDSME_fw53-18f99c7061c1', '16', '6', '(.*)', '1', '1', '2026-08-16', NULL, 'https://experience.adobe.com/?lens_env=prod&reactor-lens_version=prod20250220203018#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRffb0b6442ddd47769aad5467c2e4064f/rules/RLf0f2495fa0284801b4ae8b9b0069aa83', 'Gizem Ozturk', 'g.ozturk@partner.samsung.com', '1', NULL, NULL, '1', '2026-06-26 13:35:08', '1', '2026-06-11 10:53:42', '0', NULL, 'var script = document.createElement(\'script\');\r\nscript.src = \"https://asset.fwcdn3.com/js/fwn.js\";\r\nscript.type = \'text/javascript\';\r\nscript.async = true;\r\ndocument.head.appendChild(script);'),
('493', 'LC-Shop-AD(Firework)-OrderConfirmation-WL-SDSME_fw53-18f99c7061c1', '16', '6', '^shop order confirmation$', '1', '1', '2026-08-16', NULL, 'https://experience.adobe.com/?lens_env=prod&reactor-lens_version=prod20250220203018#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRffb0b6442ddd47769aad5467c2e4064f/rules/RL0b3cb02bb0a942889c3078758369e481', 'Gizem Ozturk', 'g.ozturk@partner.samsung.com', '1', NULL, NULL, '1', '2026-06-26 13:35:38', '1', '2026-06-16 13:47:54', '0', NULL, 'var eCommerce = digitalData.ecommerce;\r\nvar transactionId = eCommerce.transactionId;\r\n\r\nif (transactionId == \'\')\r\n    return false;\r\n\r\nvar pageInfo = digitalData.page.pageInfo;\r\nvar subTotal = 0;\r\nvar lineItems = [];\r\nvar transactionTotal = eCommerce.transactionTotal;\r\n\r\nfor (const item of eCommerce.transactionProducts) {\r\n    subTotal += item.modelPrice;\r\n    lineItems.push({\r\n        sku: item.modelCode != \'\' ? item.modelCode : item.modelName,\r\n        quantity: item.modelUnit,\r\n        price: item.modelPrice,\r\n        name: item.modelDisplay,\r\n    });\r\n}\r\n\r\nvar totalDiscounts = subTotal - transactionTotal;\r\n\r\nlet purchasePayload = {\r\n    \"order_id\": transactionId,\r\n    \"currency\": pageInfo.currencyCode,\r\n    \"subtotal\": subTotal,\r\n    \"total_discounts\": totalDiscounts,\r\n    \"order_value\": transactionTotal,\r\n    \"line_items\": lineItems,\r\n};\r\n\r\nwindow._fwn.analytics.purchase(purchasePayload);'),
('494', 'LC-AEM-AD(Contentsquare)-Cart-ATC-SDSME_9504-c48c52f97a64', '35', '3', '[an-ac=\"addToCart\"], [an-tr=\"bridge-flagship pdp-add item-option_click\"], [data-cart=\"true\"]', '6', '1', '2026-08-18', NULL, 'https://experience.adobe.com/?lens_env=prod&reactor-lens_version=prod20250220203018#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRc4ea06001baa496a85af80306c73dbb6/rules?filter%5Bname%5D=CONTAINS+LC-AEM-AD(Contentsquare)-Cart-ATC-SDSME_9504-c48c52f97a64', 'Eiass Ali', 'eiass.ali@samsung.com', '1', NULL, NULL, '1', '2026-06-19 11:06:26', '1', '2026-06-18 15:30:46', '0', NULL, NULL),
