('496', 'LC-AEM-AU(SVoucher)-CM-WL-SDSME_af29-642835946f40', '17', '39', '(.*voucher)', '1', '1', '2026-08-23', NULL, 'https://experience.adobe.com/?lens_env=prod&reactor-lens_version=prod20250220203018#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PR7defa9d2597c4d32803af3ed6c46f659/rules/RL6c15b0846af642a3ac5f8b86383ea10e', 'Lakshitha Seneviratne', 'dilshan.sl@samsung.com', '1', NULL, NULL, '1', '2026-06-24 09:36:58', '1', '2026-06-22 13:27:31', '0', NULL, 'function setSVCookie(url_param) {\r\n    const params = new URLSearchParams(window.location.search);\r\n    const rawValue = params.get(url_param);\r\n\r\n    // Sanitize: allow only alphanumeric, hyphens, underscores; max 64 chars\r\n    const sanitized = rawValue ? rawValue.replace(/[^a-zA-Z0-9\\-_]/g, \'\').slice(0, 64) : \'\';\r\n\r\n    const edate = params.get(\'edate\');\r\n    const hasEdate = edate && !isNaN(new Date(edate).getTime());\r\n    if (sanitized && (sanitized !== getSVCookie(\'svoucher\') || hasEdate)) {\r\n        const d = new Date();\r\n        if (hasEdate) {\r\n            d.setTime(new Date(edate).getTime());\r\n            d.setUTCHours(23, 59, 59, 999);\r\n        } else {\r\n            // Default: **1 week** from now\r\n            d.setDate(d.getDate() + 7);\r\n            d.setUTCHours(23, 59, 59, 999);\r\n        }\r\n        document.cookie = \"svoucher=\" + sanitized + \";expires=\" + d.toUTCString() + \";domain=.samsung.com;Secure;SameSite=Lax;path=/\";\r\n    }\r\n}\r\n\r\nfunction getSVCookie(cname = \'svoucher\') {\r\n    const name = cname + \"=\";\r\n    const cookies = document.cookie.split(\';\');\r\n    for (let i = 0; i < cookies.length; i++) {\r\n        let c = cookies[i].trimStart();\r\n        if (c.startsWith(name)) {\r\n            return c.substring(name.length);\r\n        }\r\n    }\r\n    return \"\";\r\n}\r\n\r\nsetSVCookie(\'voucher\');\r\n\r\n// Destroy cookie on order confirmation page\r\nif (typeof digitalData !== \'undefined\' && digitalData?.page?.pageInfo?.pageTrack === \'shop order confirmation\') {\r\n    document.cookie = \"svoucher=;expires=Thu, 01 Jan 1970 00:00:00 UTC;domain=.samsung.com;path=/\";\r\n}\r\n\r\n\r\nfunction waitForElement(selector, { interval = 200, timeout = 8000 } = {}) {\r\n  return new Promise((resolve, reject) => {\r\n    const start = Date.now();\r\n\r\n    // Fast‑path: element already in the DOM\r\n    const already = document.querySelector(selector);\r\n    if (already) return resolve(already);\r\n\r\n    const timer = setInterval(() => {\r\n      const el = document.querySelector(selector);\r\n      if (el) {\r\n        clearInterval(timer);\r\n        resolve(el);\r\n      } else if (Date.now() - start > timeout) {\r\n        clearInterval(timer);\r\n        reject(new Error(`Timeout – \"${selector}\" not found`));\r\n      }\r\n    }, interval);\r\n  });\r\n}\r\n\r\nasync function applyVoucher(voucherCode) {\r\n  try {\r\n\r\n    if (document.querySelector(\".voucher-applied-code .ng-star-inserted\") || !voucherCode) \r\n        return false;\r\n\r\n    const input = await waitForElement(\'#mat-input-serverApp0\');\r\n    input.focus();\r\n    input.value = voucherCode;\r\n\r\n    // ----- fire the events that the site’s validation listens to -----\r\n    input.dispatchEvent(new InputEvent(\'input\', { bubbles: true, cancelable: true, inputType: \'insertText\' }));\r\n    [\'change\', \'keyup\'].forEach(type => {\r\n      input.dispatchEvent(new Event(type, { bubbles: true }));\r\n    });\r\n\r\n    // ----- give the page a moment to run its validation -----\r\n    await new Promise(r => setTimeout(r, 500));\r\n\r\n    // ----- locate the Apply button -----\r\n    const button = await waitForElement(\r\n      \'button.pill-btn.pill-btn--black.voucher-form__btn[data-an-la=\"coupon:apply\"],\' +\r\n      \'button.pill-btn.pill-btn--black.voucher-form__btn[data-an-la=\"promo code:apply\"]\' // Secondary Apply button type\r\n    );\r\n\r\n    // Ensure button is not disabled\r\n    if (button.disabled) {\r\n      console.warn(\'Apply button is disabled – waiting a bit longer...\');\r\n      // re‑check a few times\r\n      for (let i = 0; i < 5; i++) {\r\n        await new Promise(r => setTimeout(r, 300));\r\n        if (!button.disabled) break;\r\n      }\r\n    }\r\n\r\n    if (button.disabled) return false;\r\n\r\n    // ----- click the button -----\r\n    button.click();\r\n  }\r\n  catch (err) {\r\n    console.error(\'Unable to apply voucher:\', err.message);\r\n  }\r\n}\r\n\r\nif (typeof digitalData !== \'undefined\' && digitalData?.page?.pageInfo?.pageTrack === \'shop cart\') {\r\n    applyVoucher(getSVCookie());\r\n}'),
