pe\r\n    );\r\n\r\n    // Ensure button is not disabled\r\n    if (button.disabled) {\r\n      console.warn(\'Apply button is disabled – waiting a bit longer...\');\r\n      // re‑check a few times\r\n      for (let i = 0; i < 5; i++) {\r\n        await new Promise(r => setTimeout(r, 300));\r\n        if (!button.disabled) break;\r\n      }\r\n    }\r\n\r\n    if (button.disabled) return false;\r\n\r\n    // ----- click the button -----\r\n    button.click();\r\n  }\r\n  catch (err) {\r\n    console.error(\'Unable to apply voucher:\', err.message);\r\n  }\r\n}\r\n\r\nif (typeof digitalData !== \'undefined\' && digitalData?.page?.pageInfo?.pageTrack === \'shop cart\') {\r\n    applyVoucher(getSVCookie());\r\n}'),
