('521', 'LC-AEM-AD(Firework)-Cart-ATC-SDSME_fwb5-8249346652d7', '2', '6', '[an-tr=\"bridge_add on-flagship pdp-cta-cart\"], [data-cart=\"true\"], [canaddtocart=\"true\"]', '1', '1', '2026-08-29', NULL, 'https://experience.adobe.com/#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRa7cdc4dd00c24675812c3d05053e3cf3/rules?filter%5Bname%5D=CONTAINS+LC-AEM-AD(Firework)-Cart-ATC-SDSME_fwb5-8249346652d7', 'Alaa & shereen', 'alaa.a@samsung.com', '1', NULL, NULL, '1', '2026-07-02 08:41:46', '1', '2026-06-26 13:45:38', '0', NULL, 'var currency = this.getAttribute(\'data-modelcurrency\') ?? \'N/A\';\r\nvar modelprice = this.getAttribute(\'data-modelprice\');\r\nvar price = this.getAttribute(\'data-price\');\r\nvar saveprice = this.getAttribute(\'data-save-price\');\r\nvar discountprice = this.getAttribute(\'data-discountprice\');\r\nvar originalprice = this.getAttribute(\'data-original-price\');\r\nvar subtotal = modelprice ?? price;\r\nvar total_discounts = saveprice ?? (modelprice - discountprice);\r\n\r\nvar bridgeAttr = this.getAttribute(\'an-la\');\r\nvar isBridge = (bridgeAttr == \"add-on:continue\" || bridgeAttr == \"add-on:go to cart\");\r\nvar line_items = [];\r\nvar modelcode = this.getAttribute(\'data-modelcode\');\r\nvar quantity = this.getAttribute(\'data-modelqty\');\r\nvar price = this.getAttribute(\'data-discountprice\');\r\nvar modelname = this.getAttribute(\'data-modeldisplay\');\r\n\r\nif (isBridge) {\r\n   modelcode = modelcode.split(\',\');\r\n   quantity = quantity.split(\',\');\r\n   price = price.split(\',\');\r\n   modelname = modelname.split(\',\');\r\n\r\n   modelprice = modelprice.split(\',\').map(function(v) { return Number(v.trim())});\r\n   subtotal = modelprice.reduce(function(sum, value) { return sum + value; }, 0);\r\n\r\n   discountprice = discountprice.split(\',\').map(function(v) { return Number(v.trim())});\r\n   discountprice = discountprice.reduce(function(sum, value) { return sum + value; }, 0);\r\n\r\n   total_discounts = subtotal - discountprice;\r\n\r\n    line_items = modelcode.map(function(code, index) {\r\n        return {\r\n            \"sku\": code.trim(),\r\n            \"quantity\": quantity[index] ? quantity[index].trim() : null,\r\n            \"price\": price[index] ? price[index].trim() : null,\r\n            \"name\": modelname[index] ? modelname[index].trim() : null,\r\n        };\r\n    });\r\n} else {\r\n    line_items = [{\r\n        \"sku\": modelcode,\r\n        \"quantity\": quantity,\r\n        \"price\": price,\r\n        \"name\": modelname,\r\n    }];\r\n}\r\n\r\nwindow._fwn.analytics.addToCart({\r\n    \"order_id\": \"N/A\",\r\n    \"currency\": currency,\r\n    \"subtotal\": subtotal,\r\n    \"total_discounts\": total_discounts,\r\n    \"order_value\": originalprice ? (originalprice - saveprice) : discountprice,\r\n    \"line_items\": line_items,\r\n});'),
