('543', 'LC-AEM-AD(Firework)-Cart-ATC-SDSME_fw64-3dc8e237d68f', '7', '6', '[an-tr=\"bridge_add on-flagship pdp-cta-cart\"], [data-cart=\"true\"], [canaddtocart=\"true\"]', '1', '1', '2026-09-02', NULL, 'https://experience.adobe.com/#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PR84237b02f2524aae898e192f7bab097a/rules/RLe6dae4ac4ab74999a5333440e031ff2d', 'Yara Mustafa Afifi', 'yara.a@partner.samsung.com', '1', NULL, NULL, '1', '2026-07-07 15:47:56', '1', '2026-07-01 12:43:22', '0', NULL, 'var currency = this.getAttribute(\'data-modelcurrency\') ?? \'N/A\';\r\nvar modelprice = this.getAttribute(\'data-modelprice\');\r\nvar price = this.getAttribute(\'data-price\');\r\nvar saveprice = this.getAttribute(\'data-save-price\');\r\nvar discountprice = this.getAttribute(\'data-discountprice\');\r\nvar originalprice = this.getAttribute(\'data-original-price\');\r\nvar subtotal = modelprice ?? price;\r\nvar total_discounts = saveprice ?? (modelprice - discountprice);\r\n\r\nvar bridgeAttr = this.getAttribute(\'an-la\');\r\nvar isBridge = (bridgeAttr == \"add-on:continue\" || bridgeAttr == \"add-on:go to cart\");\r\nvar line_items = [];\r\nvar modelcode = this.getAttribute(\'data-modelcode\');\r\nvar quantity = this.getAttribute(\'data-modelqty\');\r\nvar price = this.getAttribute(\'data-discountprice\');\r\nvar modelname = this.getAttribute(\'data-modeldisplay\');\r\n\r\nif (isBridge) {\r\n   modelcode = modelcode.split(\',\');\r\n   quantity = quantity.split(\',\');\r\n   price = price.split(\',\');\r\n   modelname = modelname.split(\',\');\r\n\r\n   modelprice = modelprice.split(\',\').map(function(v) { return Number(v.trim())});\r\n   subtotal = modelprice.reduce(function(sum, value) { return sum + value; }, 0);\r\n\r\n   discountprice = discountprice.split(\',\').map(function(v) { return Number(v.trim())});\r\n   discountprice = discountprice.reduce(function(sum, value) { return sum + value; }, 0);\r\n\r\n   total_discounts = subtotal - discountprice;\r\n\r\n    line_items = modelcode.map(function(code, index) {\r\n        return {\r\n            \"sku\": code.trim(),\r\n            \"quantity\": quantity[index] ? quantity[index].trim() : null,\r\n            \"price\": price[index] ? price[index].trim() : null,\r\n            \"name\": modelname[index] ? modelname[index].trim() : null,\r\n        };\r\n    });\r\n} else {\r\n    line_items = [{\r\n        \"sku\": modelcode,\r\n        \"quantity\": quantity,\r\n        \"price\": price,\r\n        \"name\": modelname,\r\n    }];\r\n}\r\n\r\nwindow._fwn.analytics.addToCart({\r\n    \"order_id\": \"N/A\",\r\n    \"currency\": currency,\r\n    \"subtotal\": subtotal,\r\n    \"total_discounts\": total_discounts,\r\n    \"order_value\": originalprice ? (originalprice - saveprice) : discountprice,\r\n    \"line_items\": line_items,\r\n});'),
('544', 'LC-Shop-AD(Firework)-CM(ALL)-WL-SDSME_fw11-fb62c6a234cf', '12', '6', '(.*)', '1', '1', '2026-09-02', NULL, 'https://experience.adobe.com/?lens_env=prod&reactor-lens_version=prod20250220203018#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRc6bfd8cde63246ee8abe23e880a2ae2f/rules/RL2dd62b37046f41648ec913bc82e9a056', 'Yara Mustafa Afifi', 'yara.a@partner.samsung.com', '1', NULL, NULL, '1', '2026-07-07 15:47:54', '1', '2026-07-01 12:45:47', '0', NULL, 'var script = document.createElement(\'script\');\r\nscript.src = \"https://asset.fwcdn3.com/js/fwn.js\";\r\nscript.type = \'text/javascript\';\r\nscript.async = true;\r\ndocument.head.appendChild(script);'),
('545', 'LC-Shop-AD(Firework)-OrderConfirmation-WL-SDSME_fw11-fb62c6a234cf', '12', '6', '^shop order confirmation$', '1', '1', '2026-09-02', NULL, 'https://experience.adobe.com/?lens_env=prod&reactor-lens_version=prod20250220203018#/@samsung/data-collection/tags/companies/COae164dc89349443cb5092e1fdc571f55/properties/PRc6bfd8cde63246ee8abe23e880a2ae2f/rules/RLd9ddf4d8a59347609046bf01bc8a30b5', 'Yara Mustafa Afifi', 'yara.a@partner.samsung.com', '1', NULL, NULL, '1', '2026-07-07 15:47:54', '1', '2026-07-01 12:45:47', '0', NULL, 'if (!window.fwOrderCount) window.fwOrderCount = 0; //prevent duplicate orders\r\n\r\nvar eCommerce = digitalData.ecommerce;\r\nvar transactionId = eCommerce.transactionId;\r\n\r\nif (transactionId == \'\' || window.fwOrderCount > 1) return false; // on page refresh\r\n\r\nvar pageInfo = digitalData.page.pageInfo;\r\nvar subTotal = 0;\r\nvar lineItems = [];\r\nvar transactionTotal = eCommerce.transactionTotal;\r\n\r\nfor (const item of eCommerce.transactionProducts) {\r\n    subTotal += item.modelPrice;\r\n    lineItems.push({\r\n        sku: item.modelCode != \'\' ? item.modelCode : item.modelName,\r\n        quantity: item.modelUnit,\r\n        price: item.modelPrice,\r\n        name: item.modelDisplay,\r\n    });\r\n}\r\n\r\nvar totalDiscounts = 0;\r\nif (subTotal > 0)\r\n  totalDiscounts = subTotal - transactionTotal;\r\n\r\nlet purchasePayload = {\r\n    \"order_id\": transactionId,\r\n    \"currency\": pageInfo.currencyCode,\r\n    \"subtotal\": subTotal,\r\n    \"total_discounts\": totalDiscounts,\r\n    \"order_value\": transactionTotal,\r\n    \"line_items\": lineItems,\r\n};\r\n\r\nwindow._fwn.analytics.purchase(purchasePayload);\r\nwindow.fwOrderCount++;'),
