('7', 'Pinterest', '', '<p><span style=\"font-size: 14.4px;\">Fully track user journey\'s across the website from activated campaigns on Pinterest Ads.</span></p>', '', NULL, '1', '1', '2026-06-26 10:14:17', '0', '2026-05-06 13:16:06', '0', NULL),
('8', 'CJ', '<p>Track affiliate link &amp; voucher sales</p>', '<p>Track affiliate link &amp; voucher sales</p>', '<p>CJ is an aggregator that will help us scale our affiliate marketing activations through different types of networks and publishers that all serve as affiliate marketing</p>', NULL, '1', '1', '2026-07-01 14:04:01', '0', '2026-05-06 13:24:45', '0', NULL),
('9', 'Meta', '', '<p><span style=\"color: rgb(23, 43, 77); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Oxygen, Ubuntu, &quot;Fira Sans&quot;, &quot;Droid Sans&quot;, &quot;Helvetica Neue&quot;, sans-serif; font-size: 14px;\">Facebook Meta pixel is required by HQ and local subsidiary</span></p>', '<p><span style=\"color: rgb(23, 43, 77); font-family: -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, Oxygen, Ubuntu, &quot;Fira Sans&quot;, &quot;Droid Sans&quot;, &quot;Helvetica Neue&quot;, sans-serif; font-size: 14px;\">Facebook Meta pixel is required by HQ and local subsidiary</span></p>', NULL, '1', '1', '2026-06-10 09:56:44', '0', '2026-05-15 11:22:28', '0', NULL),
('10', 'AdobeDSP', NULL, 'As we are using Adobe Analytics to measure performance, we plan to use Adobe Advertising Cloud DSP for all Samsung campaigns moving forward. In Adobe Analytics, we would like to track both view-through and click-through conversions from Adobe Advertising Cloud DSP for all Samsung campaigns. To track view-through conversions, we would need to implement the required JavaScript code.', 'As we are using Adobe Analytics to measure performance, we plan to use Adobe Advertising Cloud DSP for all Samsung campaigns moving forward. In Adobe Analytics, we would like to track both view-through and click-through conversions from Adobe Advertising Cloud DSP for all Samsung campaigns. To track view-through conversions, we would need to implement the required JavaScript code.', NULL, '1', '0', '2026-05-15 12:32:06', '0', '2026-05-15 12:32:06', '0', NULL),
