('39', 'SVoucher', '', '', '<p><span style=\"font-size: 14.4px;\">This tag is for directly applying voucher codes on the Samsung checkout page when a user clicks on a promotion message sent via any messaging platform, to be used for campaigns. This tag will only proceed when the \'<b>voucher</b>\' parameter is present in the URL. (ex: </span><a href=\"https://www.samsung.com/ae?voucher=50OFF\" target=\"_blank\">https://www.samsung.com/ae?voucher=50OFF</a><span style=\"font-size: 14.4px;\"> )</span></p>', NULL, '1', '1', '2026-06-24 10:49:20', '1', '2026-06-22 13:27:31', '0', NULL),
('40', 'AmazonDSP', '', '<p><span style=\"font-size: 14.4px;\">Amazon DSP pixels to track user interactions and attributed sales in real time across the website. The implementation will enable tracking of key conversion events including Page Views, View Content, Add to Cart, Checkout, and Purchase to support campaign optimization, audience building, attribution, and performance measurement for Amazon DSP campaigns.</span></p>', '<p><span style=\"font-size: 14.4px;\">Amazon DSP pixels to track user interactions and attributed sales in real time across the website. The implementation will enable tracking of key conversion events including Page Views, View Content, Add to Cart, Checkout, and Purchase to support campaign optimization, audience building, attribution, and performance measurement for Amazon DSP campaigns.</span></p>', NULL, '1', '1', '2026-06-24 11:48:25', '1', '2026-06-23 14:30:22', '0', NULL);
